//! Safe, local generation and execution of a small GitHub Actions CI surface.
//!
//! The scanner reads repository metadata only. It never evaluates a build file,
//! package manifest, hook, or project command. Commands are drafted into
//! `.github/ci/project.toml`; the checked-in configuration is the runtime
//! source of truth after generation.

use std::collections::{BTreeMap, BTreeSet};
use std::env;
use std::ffi::OsString;
use std::fmt::Write as _;
use std::fs;
use std::io::{self, IsTerminal, Read as _, Write as _};
use std::path::{Component, Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::{SystemTime, UNIX_EPOCH};

use clap::{Parser, ValueEnum};
use serde_json::Value;
use sha2::{Digest as _, Sha256};

mod runtime;
mod tui;

