pub enum ActionPin {
    Checkout,
    CacheRestore,
    CacheSave,
    OpenTofuSetup,
    UploadArtifact,
    DownloadArtifact,
    Bun,
    Node,
    RustTool,
    Mise,
    Gradle,
    Sccache,
    MrBoxington,
    Mold,
    GithubRuntime,
    DockerBuildx,
    DockerLogin,
    DockerQemu,
    DockerBuild,
    Cosign,
    Attest,
    CratesAuth,
    ConfigurePages,
    UploadPages,
    DeployPages,
}

