const FOUR_TARGETS: &[&str] = &[
    "x86_64-unknown-linux-gnu",
    "aarch64-unknown-linux-gnu",
    "x86_64-apple-darwin",
    "aarch64-apple-darwin",
];
const LINUX_TARGETS: &[&str] = &["x86_64-unknown-linux-gnu", "aarch64-unknown-linux-gnu"];

fn estate_profile(repository: &str) -> Option<&'static EstateProfile> {
    ESTATE_PROFILES
        .iter()
        .find(|profile| profile.repository == repository)
}

fn estate_workflow_files(profile: &EstateProfile) -> Vec<String> {
    if !profile.verified {
        return Vec::new();
    }
    let mut files = vec![
        "ci-pr.yml".to_owned(),
        "ci-policy.yml".to_owned(),
        "ci-main.yml".to_owned(),
    ];
    if matches!(
        profile.profile,
        RepositoryProfile::RustWorkspaceNative
            | RepositoryProfile::RustCli
            | RepositoryProfile::RustObservabilityCli
    ) {
        files.push("preview.yml".to_owned());
    }
    if release_spec(profile).is_some() {
        files.push("release.yml".to_owned());
    }
    if profile.repository == "tailrocks/velnor" {
        files.push(VELNOR_RELEASE_PACKAGE_SIGNER_WORKFLOW.to_owned());
        files.push(VELNOR_POLICY_PROVIDER_WORKFLOW.to_owned());
    }
    if matches!(
        profile.profile,
        RepositoryProfile::RustWorkspaceNative
            | RepositoryProfile::RustWorkspaceRelease
            | RepositoryProfile::RustObservabilityCli
            | RepositoryProfile::SkillsContent
            | RepositoryProfile::PolyglotMonorepo
            | RepositoryProfile::DockerFleet
    ) {
        files.push("nightly.yml".to_owned());
    }
    files.push("maintenance.yml".to_owned());
    files
}

fn apply_local_velnor_profile(
    root: &Path,
    mut config: ProjectConfig,
) -> Result<ProjectConfig, GeneratorError> {
    if local_github_repository(root).as_deref() != Some("tailrocks/velnor") {
        enable_mr_boxington_commands(&mut config);
        return Ok(config);
    }
    let Some(profile) = estate_profile("tailrocks/velnor") else {
        enable_mr_boxington_commands(&mut config);
        return Ok(config);
    };
    let release = profile.verified.then(|| release_spec(profile)).flatten();
    profile.repository.clone_into(&mut config.repository);
    config.profile = profile.profile;
    config.verified = profile.verified;
    config.workflow_files = estate_workflow_files(profile);
    config.release_enabled = release.is_some();
    config.release_reason = if release.is_some() {
        "Release contract is explicitly cataloged; review credentials, environments, and tag protection before cutover.".to_owned()
    } else {
        "Release is fail-closed until source, artifact, registry, provenance, and credential contracts are verified.".to_owned()
    };
    config.release = release;
    config.version_bump_units = vec![
        "docker".to_owned(),
        "rust-velnor-bench".to_owned(),
        "rust-velnor-runner".to_owned(),
        "rust-velnorctl".to_owned(),
    ];
    if !config
        .units
        .iter()
        .any(|unit| unit.id == "rust-production-topology")
    {
        config.units.push(Unit {
            id: "rust-production-topology".to_owned(),
            label: "Rust production topology".to_owned(),
            kind: UnitKind::Rust,
            root: ".".to_owned(),
            watch: vec![
                ".cargo/**".to_owned(),
                "Cargo.toml".to_owned(),
                "Cargo.lock".to_owned(),
                "crates/**".to_owned(),
                "docker/**".to_owned(),
                "microvm/**".to_owned(),
                "mise.lock".to_owned(),
                "mise.toml".to_owned(),
                "rust-toolchain".to_owned(),
                "rust-toolchain.toml".to_owned(),
                "tools/**".to_owned(),
            ],
            pr_commands: vec![
                "cargo check --workspace --all-targets --locked".to_owned(),
                "mise run test-release-feature-boundary".to_owned(),
            ],
            full_commands: vec![
                "cargo check --workspace --all-targets --locked".to_owned(),
                "mise run test-release-feature-boundary".to_owned(),
            ],
            github_pr_commands: None,
            github_full_commands: None,
            velnor_pr_commands: None,
            velnor_full_commands: None,
            depends_on: Vec::new(),
            cache: Some(CacheSpec {
                key_files: vec!["Cargo.toml".to_owned(), "Cargo.lock".to_owned()],
                paths: vec!["~/.cargo/registry".to_owned(), "~/.cargo/git".to_owned()],
            }),
            tool_version: None,
        });
    }
    apply_velnor_watch_graph(root, &mut config)?;
    configure_velnor_docker_pr_target(&mut config);
    add_velnor_regeneration_gate(&mut config);
    enable_mr_boxington_commands(&mut config);
    Ok(config)
}

fn configure_velnor_docker_pr_target(config: &mut ProjectConfig) {
    for unit in config
        .units
        .iter_mut()
        .filter(|unit| unit.kind == UnitKind::Docker && unit.root == ".")
    {
        for command in &mut unit.pr_commands {
            let Some(arguments) = command.strip_prefix("docker build ") else {
                continue;
            };
            if !arguments.contains("--file 'Dockerfile'") {
                continue;
            }
            *command = format!("docker build --target ci {arguments}");
        }
    }
}

fn add_velnor_regeneration_gate(config: &mut ProjectConfig) {
    let Some(unit) = config
        .units
        .iter_mut()
        .find(|unit| unit.id == "rust-velnor-workflow")
    else {
        return;
    };
    // The workflow crate owns the checked-in templates and generated caller
    // surface. Run the generator in check mode from the repository root so a
    // template-only edit cannot pass without regenerating its consumers.
    let command = "cd -- 'crates/velnor-workflow' && mbx run --locked --manifest-path 'Cargo.toml' -- --plain --check ../..";
    if !unit
        .pr_commands
        .iter()
        .any(|candidate| candidate == command)
    {
        unit.pr_commands.insert(0, command.to_owned());
    }
    if !unit
        .full_commands
        .iter()
        .any(|candidate| candidate == command)
    {
        unit.full_commands.insert(0, command.to_owned());
    }
}

fn apply_velnor_watch_graph(root: &Path, config: &mut ProjectConfig) -> Result<(), GeneratorError> {
    let files = repository_files(root)?;
    let file_set = files.iter().cloned().collect::<BTreeSet<_>>();
    let docker_watch = docker_watch_paths(root, &config.units)?;
    // `runtime.rs` executes in every generated job, so its selection and
    // command-contract changes are broad-impact. `lib.rs` is the generator
    // and already belongs to the workflow crate plus the Docker image that
    // packages the runtime. Keeping it out of this common list prevents a
    // generator-only edit from selecting every verification unit; stale
    // generated output is then caught by the workflow unit's regeneration
    // gate, while changed generated `.github/**` output still fails closed to
    // full selection in the runtime.
    let common_runtime_inputs = ["crates/velnor-workflow/src/runtime.rs"];
    for unit in &mut config.units {
        if unit.kind == UnitKind::Docker && unit.root == "." {
            unit.watch.clone_from(&docker_watch);
        }
        match unit.id.as_str() {
            "bun-velnor" => {
                unit.watch = vec![
                    "package.json".to_owned(),
                    "bun.lock".to_owned(),
                    "bun.lockb".to_owned(),
                    "package-lock.json".to_owned(),
                    "src/**".to_owned(),
                    "scripts/**".to_owned(),
                ];
                unit.watch.extend(
                    files
                        .iter()
                        .filter(|file| {
                            parent_path(file) == "."
                                && (file.ends_with(".config.js")
                                    || file.ends_with(".config.ts")
                                    || file.as_str() == "tsconfig.json")
                        })
                        .cloned(),
                );
            }
            "docs" => {
                unit.watch = vec!["content/docs/**/*.mdx".to_owned(), "*.md".to_owned()];
            }
            "opentofu" => {
                unit.watch = files
                    .iter()
                    .filter(|file| {
                        !is_test_support_path(file)
                            && (has_extension(file, "tf")
                                || has_extension(file, "tofu")
                                || file.rsplit('/').next() == Some(".terraform.lock.hcl"))
                    })
                    .cloned()
                    .collect();
            }
            _ => {}
        }
        if matches!(unit.kind, UnitKind::Rust | UnitKind::Docker) {
            unit.watch.extend([
                ".cargo/**".to_owned(),
                "Cargo.toml".to_owned(),
                "Cargo.lock".to_owned(),
                "rust-toolchain.toml".to_owned(),
                "rust-toolchain".to_owned(),
                "mise.toml".to_owned(),
                "mise.lock".to_owned(),
            ]);
        }
        unit.watch
            .extend(common_runtime_inputs.iter().map(|path| (*path).to_owned()));
        if unit.id == "rust-velnor-workflow" {
            unit.watch.extend([
                "crates/velnor-workflow/templates/**".to_owned(),
                "crates/velnor-workflow/README.md".to_owned(),
            ]);
        }
        if unit.id == "rust-velnor-runner" {
            unit.watch.extend([
                "crates/velnor-workflow/templates/velnor-release.yml".to_owned(),
                "microvm/**".to_owned(),
                "tools/unit-collector/**".to_owned(),
            ]);
        }
        if unit.id == "rust-velnorctl" {
            unit.watch.push("microvm/**".to_owned());
        }
        if unit.id == "rust-velnor-model" {
            for prefix in ["schema/", "schemas/"] {
                if file_set.iter().any(|file| file.starts_with(prefix)) {
                    unit.watch.push(format!("{prefix}**"));
                }
            }
        }
        if matches!(unit.kind, UnitKind::Rust | UnitKind::Docker)
            && file_set.iter().any(|file| file.starts_with("fleet/"))
        {
            unit.watch.push("fleet/**".to_owned());
        }
        unit.watch.sort();
        unit.watch.dedup();
    }
    Ok(())
}

fn docker_watch_paths(root: &Path, units: &[Unit]) -> Result<Vec<String>, GeneratorError> {
    let files = repository_files(root)?;
    let file_set = files.iter().cloned().collect::<BTreeSet<_>>();
    let mut watch = BTreeSet::from([
        ".dockerignore".to_owned(),
        "Cargo.lock".to_owned(),
        "Cargo.toml".to_owned(),
        "Dockerfile".to_owned(),
        "docker/**".to_owned(),
        "mise.lock".to_owned(),
        "mise.toml".to_owned(),
        "rust-toolchain".to_owned(),
        "rust-toolchain.toml".to_owned(),
        ".cargo/**".to_owned(),
    ]);
    for dockerfile in files.iter().filter(|file| {
        !is_test_support_path(file)
            && parent_path(file) == "."
            && file
                .rsplit('/')
                .next()
                .is_some_and(|name| name.starts_with("Dockerfile"))
    }) {
        let contents = fs::read_to_string(root.join(dockerfile)).map_err(|error| {
            GeneratorError::io("read Dockerfile", &root.join(dockerfile), &error)
        })?;
        for line in contents.lines() {
            let tokens = line
                .split_whitespace()
                .take_while(|token| !token.starts_with('#'))
                .collect::<Vec<_>>();
            let Some(command) = tokens.first().map(|token| token.to_ascii_uppercase()) else {
                continue;
            };
            if !matches!(command.as_str(), "COPY" | "ADD")
                || tokens.iter().any(|token| token.starts_with("--from="))
            {
                continue;
            }
            let sources = tokens
                .iter()
                .skip(1)
                .filter(|token| !token.starts_with("--"))
                .take(tokens.len().saturating_sub(2))
                .map(|token| token.trim_matches(['\'', '"']))
                .collect::<Vec<_>>();
            for source in sources {
                if source.starts_with('/') || source.contains('$') || source.contains("://") {
                    continue;
                }
                let source = source.trim_start_matches("./").trim_end_matches('/');
                if source.is_empty() || source == "." {
                    return Err(GeneratorError::usage(format!(
                        "Dockerfile source is too broad for affected CI: {dockerfile}"
                    )));
                }
                if file_set.contains(source) {
                    watch.insert(source.to_owned());
                } else if file_set
                    .iter()
                    .any(|file| file.starts_with(&format!("{source}/")))
                {
                    watch.insert(format!("{source}/**"));
                } else {
                    return Err(GeneratorError::usage(format!(
                        "Dockerfile COPY/ADD source does not exist: {dockerfile}: {source}"
                    )));
                }
            }
        }
    }
    let seeds = [
        "rust-velnor-runner",
        "rust-velnorctl",
        "rust-velnor-tools",
        "rust-velnor-workflow",
    ]
    .into_iter()
    .filter(|id| units.iter().any(|unit| unit.id == *id))
    .map(str::to_owned)
    .collect::<BTreeSet<_>>();
    let mut closure = seeds.clone();
    let mut pending = seeds.into_iter().collect::<Vec<_>>();
    while let Some(id) = pending.pop() {
        if let Some(unit) = units.iter().find(|unit| unit.id == id) {
            for dependency in &unit.depends_on {
                if closure.insert(dependency.clone()) {
                    pending.push(dependency.clone());
                }
            }
        }
    }
    for unit in units.iter().filter(|unit| closure.contains(&unit.id)) {
        if unit.root != "." {
            watch.insert(format!("{}/**", unit.root));
        }
    }
    Ok(watch.into_iter().collect())
}

fn enable_mr_boxington_commands(config: &mut ProjectConfig) {
    let is_velnor = config.repository == "tailrocks/velnor";
    for unit in &mut config.units {
        if unit.kind == UnitKind::Rust {
            unit.pr_commands = unit
                .pr_commands
                .iter()
                .map(|command| mbxify_cargo_command(command))
                .collect();
            unit.full_commands = unit
                .full_commands
                .iter()
                .map(|command| mbxify_cargo_command(command))
                .collect();
        } else if is_velnor && unit.kind == UnitKind::Docker {
            let github_pr_commands = unit
                .pr_commands
                .iter()
                .map(|command| github_docker_cache_command(command, false))
                .collect::<Vec<_>>();
            let github_full_commands = unit
                .full_commands
                .iter()
                .map(|command| github_docker_cache_command(command, true))
                .collect::<Vec<_>>();
            let velnor_pr_commands = unit
                .pr_commands
                .iter()
                .map(|command| velnor_docker_command(command))
                .collect::<Vec<_>>();
            let velnor_full_commands = unit
                .full_commands
                .iter()
                .map(|command| velnor_docker_command(command))
                .collect::<Vec<_>>();
            unit.github_pr_commands = Some(github_pr_commands);
            unit.github_full_commands = Some(github_full_commands);
            unit.velnor_pr_commands = Some(velnor_pr_commands);
            unit.velnor_full_commands = Some(velnor_full_commands);
        }
        unit.watch.sort();
        unit.watch.dedup();
    }
    if config.units.iter().any(|unit| unit.kind == UnitKind::Rust) {
        config.notes.push(format!(
            "Rust verification uses Mr. Boxington {MR_BOXINGTON_VERSION} by default on both lanes. GitHub-hosted jobs use its GitHub cache backend with stable per-unit keys (exact hits reuse the cache; a new entry is saved only when dependency inputs change). Velnor jobs use an explicit local-backend setup step against the image/runner-provided local store."
        ));
    }
}

fn mbxify_cargo_command(command: &str) -> String {
    if command.contains("velnor-workflow test-crates") {
        return if command.contains(MR_BOXINGTON_ENABLED_ENV) {
            command.to_owned()
        } else {
            format!("{MR_BOXINGTON_ENABLED_ENV}=1 {command}")
        };
    }
    mbxify_cargo_invocations(command).0
}

fn is_mr_boxington_cargo_subcommand(token: &str) -> bool {
    MR_BOXINGTON_CARGO_SUBCOMMANDS.contains(&token)
}

fn next_shell_token(input: &str, start: usize) -> Option<(usize, usize)> {
    let start = start
        + input[start..]
            .bytes()
            .take_while(u8::is_ascii_whitespace)
            .count();
    let first = *input.as_bytes().get(start)?;
    if matches!(first, b'\'' | b'"') {
        let mut index = start + 1;
        while index < input.len() {
            if input.as_bytes()[index] == first {
                return Some((start, index + 1));
            }
            index += 1;
        }
        return None;
    }
    let end = start
        + input[start..]
            .bytes()
            .take_while(|byte| !byte.is_ascii_whitespace())
            .count();
    Some((start, end))
}

fn is_word_boundary_before(input: &str, index: usize) -> bool {
    input
        .as_bytes()
        .get(index.wrapping_sub(1))
        .is_none_or(|byte| !byte.is_ascii_alphanumeric() && *byte != b'_' && *byte != b'-')
}

fn is_cargo_token(input: &str, index: usize) -> bool {
    input
        .get(index..index + "cargo".len())
        .is_some_and(|token| token == "cargo")
        && is_word_boundary_before(input, index)
        && input
            .as_bytes()
            .get(index + "cargo".len())
            .is_some_and(u8::is_ascii_whitespace)
}

fn is_mbx_token(input: &str, index: usize) -> bool {
    input
        .get(index..index + "mbx".len())
        .is_some_and(|token| token == "mbx")
        && is_word_boundary_before(input, index)
        && input
            .as_bytes()
            .get(index + "mbx".len())
            .is_some_and(u8::is_ascii_whitespace)
}

fn is_shell_command_separator(token: &str) -> bool {
    matches!(token, "&&" | "||" | "|" | ";" | "&")
}

fn strip_mbx_no_deps(input: &str) -> String {
    let mut output = String::with_capacity(input.len());
    let mut cursor = 0;
    let mut mbx_pending_subcommand = false;
    let mut mbx_check_or_clippy = false;
    while let Some((start, end)) = next_shell_token(input, cursor) {
        if input[cursor..start].contains('\n') {
            mbx_pending_subcommand = false;
            mbx_check_or_clippy = false;
        }
        let token = &input[start..end];
        if mbx_check_or_clippy && token == "--no-deps" {
            // Mr. Boxington's check and clippy wrappers intentionally do not
            // expose Cargo's `--no-deps` option.
            cursor = end;
        } else {
            output.push_str(&input[cursor..end]);
            cursor = end;
        }

        if is_shell_command_separator(token) {
            mbx_pending_subcommand = false;
            mbx_check_or_clippy = false;
        } else if mbx_check_or_clippy {
            // Keep the state until the shell command ends so flags can be
            // removed regardless of their position in the invocation.
        } else if mbx_pending_subcommand {
            if matches!(token, "check" | "clippy") {
                mbx_pending_subcommand = false;
                mbx_check_or_clippy = true;
            } else if !token.starts_with('+') || token.len() == 1 {
                mbx_pending_subcommand = false;
            }
        } else if token == "mbx" {
            mbx_pending_subcommand = true;
        }
    }
    output.push_str(&input[cursor..]);
    output
}

fn mbxify_rustup_cargo_invocations(input: &str) -> (String, bool) {
    let mut output = String::with_capacity(input.len());
    let mut cursor = 0;
    let mut changed = false;
    while let Some(relative_start) = input[cursor..].find("rustup run ") {
        let start = cursor + relative_start;
        if !is_word_boundary_before(input, start) {
            cursor = start + "rustup".len();
            continue;
        }
        let toolchain_start = start + "rustup run ".len();
        let Some((toolchain_start, toolchain_end)) = next_shell_token(input, toolchain_start)
        else {
            cursor = toolchain_start;
            continue;
        };
        let Some((cargo_start, cargo_end)) = next_shell_token(input, toolchain_end) else {
            cursor = toolchain_end;
            continue;
        };
        if !is_cargo_token(input, cargo_start) {
            cursor = cargo_end;
            continue;
        }
        let Some((subcommand_start, subcommand_end)) = next_shell_token(input, cargo_end) else {
            cursor = cargo_end;
            continue;
        };
        let subcommand = &input[subcommand_start..subcommand_end];
        if !is_mr_boxington_cargo_subcommand(subcommand) {
            cursor = subcommand_end;
            continue;
        }
        output.push_str(&input[cursor..start]);
        output.push_str("mbx +");
        output.push_str(&input[toolchain_start..toolchain_end]);
        cursor = cargo_end;
        changed = true;
    }
    output.push_str(&input[cursor..]);
    (output, changed)
}

fn mbxify_cargo_invocations(input: &str) -> (String, bool) {
    let (input, rustup_changed) = mbxify_rustup_cargo_invocations(input);
    let mut output = String::with_capacity(input.len());
    let mut cursor = 0;
    let mut changed = rustup_changed;
    while let Some(relative_start) = input[cursor..].find("cargo") {
        let start = cursor + relative_start;
        if !is_cargo_token(&input, start) {
            output.push_str(&input[cursor..start + "cargo".len()]);
            cursor = start + "cargo".len();
            continue;
        }
        let cargo_end = start + "cargo".len();
        let Some((subcommand_start, subcommand_end)) = next_shell_token(&input, cargo_end) else {
            output.push_str(&input[cursor..]);
            return (output, changed);
        };
        let subcommand = &input[subcommand_start..subcommand_end];
        output.push_str(&input[cursor..start]);
        if is_mr_boxington_cargo_subcommand(subcommand) {
            output.push_str("mbx");
            changed = true;
        } else {
            output.push_str("cargo");
        }
        cursor = cargo_end;
    }
    output.push_str(&input[cursor..]);
    let normalized = strip_mbx_no_deps(&output);
    let changed = changed || normalized != output;
    (normalized, changed)
}

const STATIC_MR_BOXINGTON_STEP: &str = r"      - name: Set up Mr. Boxington
        uses: jdx/mr-boxington-action@7234d3dd1a6ca8f6c381eea8e4dfb03f18fcf777 # v1.3.0
        with:
          backend: github
          version: 1.8.3
          cache-key: velnor-static-mbx-1.8.3-${{ runner.os }}-${{ runner.arch }}-${{ github.workflow }}-${{ github.job }}-${{ hashFiles('Cargo.lock', 'rust-toolchain.toml', 'rust-toolchain', 'mise.toml', 'mise.lock', '**/Cargo.toml') }}
          restore-keys: |
            velnor-static-mbx-1.8.3-${{ runner.os }}-${{ runner.arch }}-${{ github.workflow }}-${{ github.job }}-
          save-on-workflow-dispatch: true
";

fn static_workflow_job_ranges(lines: &[String]) -> Vec<(usize, usize)> {
    let Some(jobs_start) = lines.iter().position(|line| {
        line.trim_end_matches(['\n', '\r']) == "jobs:"
            && line.chars().take_while(char::is_ascii_whitespace).count() == 0
    }) else {
        return Vec::new();
    };
    let job_starts = lines
        .iter()
        .enumerate()
        .skip(jobs_start + 1)
        .take_while(|(_, line)| {
            let trimmed = line.trim();
            trimmed.is_empty()
                || line
                    .chars()
                    .next()
                    .is_some_and(|character| character.is_ascii_whitespace())
        })
        .filter_map(|(index, line)| {
            let trimmed = line.trim();
            let indentation = line.len() - line.trim_start().len();
            (indentation == 2 && trimmed.ends_with(':') && !trimmed.starts_with('-'))
                .then_some(index)
        })
        .collect::<Vec<_>>();
    job_starts
        .iter()
        .enumerate()
        .map(|(index, &start)| {
            let end = job_starts.get(index + 1).copied().unwrap_or(lines.len());
            (start, end)
        })
        .collect()
}

fn line_has_mbx_cargo_invocation(line: &str) -> bool {
    let mut cursor = 0;
    while let Some(relative_start) = line[cursor..].find("mbx") {
        let start = cursor + relative_start;
        if is_mbx_token(line, start) {
            let mbx_end = start + "mbx".len();
            let Some((token_start, token_end)) = next_shell_token(line, mbx_end) else {
                return false;
            };
            let token = &line[token_start..token_end];
            if let Some(toolchain) = token.strip_prefix('+') {
                if !toolchain.is_empty()
                    && next_shell_token(line, token_end).is_some_and(|(start, end)| {
                        is_mr_boxington_cargo_subcommand(&line[start..end])
                    })
                {
                    return true;
                }
            } else if is_mr_boxington_cargo_subcommand(token) {
                return true;
            }
        }
        cursor = start + "mbx".len();
    }
    false
}

fn static_workflow_step_start(line: &str) -> bool {
    line.len() - line.trim_start().len() == 6 && line.trim_start().starts_with("- ")
}

fn ensure_static_mr_boxington_steps(lines: &mut Vec<String>) {
    let ranges = static_workflow_job_ranges(lines);
    let mut insertions = Vec::new();
    for (job_start, job_end) in ranges {
        if !lines[job_start..job_end]
            .iter()
            .any(|line| line.contains("jdx/mr-boxington-action@"))
            && lines[job_start..job_end]
                .iter()
                .any(|line| line_has_mbx_cargo_invocation(line))
        {
            let Some(steps_start) = (job_start..job_end).find(|&index| {
                let line = &lines[index];
                line.len() - line.trim_start().len() == 4 && line.trim() == "steps:"
            }) else {
                continue;
            };
            let step_starts = (steps_start + 1..job_end)
                .filter(|&index| static_workflow_step_start(&lines[index]))
                .collect::<Vec<_>>();
            let insert_at = step_starts
                .iter()
                .enumerate()
                .find_map(|(index, &step_start)| {
                    let step_end = step_starts.get(index + 1).copied().unwrap_or(job_end);
                    lines[step_start..step_end]
                        .iter()
                        .any(|line| line.contains("actions/checkout@"))
                        .then_some(step_end)
                })
                .or_else(|| step_starts.first().copied())
                .unwrap_or(steps_start + 1);
            insertions.push((insert_at, STATIC_MR_BOXINGTON_STEP.to_owned()));
        }
    }
    for (index, step) in insertions.into_iter().rev() {
        lines.insert(index, step);
    }
}

fn refresh_static_mr_boxington_commands(template: &str) -> String {
    let mut lines = template
        .split_inclusive('\n')
        .map(str::to_owned)
        .collect::<Vec<_>>();
    for line in &mut lines {
        line.clone_from(&mbxify_cargo_invocations(line).0);
    }
    ensure_static_mr_boxington_steps(&mut lines);
    lines.concat()
}

fn github_docker_cache_command(command: &str, write_cache: bool) -> String {
    let Some(arguments) = command.strip_prefix("docker build ") else {
        return command.to_owned();
    };
    let cache_to = write_cache
        .then_some(" --cache-to type=gha,mode=max,scope=velnor-docker,ignore-error=true");
    format!(
        "docker buildx build --load --cache-from type=gha,scope=velnor-docker{} {arguments}",
        cache_to.unwrap_or_default()
    )
}

fn velnor_docker_command(command: &str) -> String {
    let Some(arguments) = command.strip_prefix("docker build ") else {
        return command.to_owned();
    };
    format!("docker buildx build --load {arguments}")
}

fn reject_retired_workflow_provider_reference(
    path: &Path,
    content: &str,
) -> Result<(), GeneratorError> {
    let contains_reference = match serde_yaml::from_str::<serde_yaml::Value>(content) {
        Ok(document) => yaml_contains_retired_workflow_provider(&document),
        Err(_) => content
            .lines()
            .filter_map(workflow_uses_value)
            .any(is_retired_workflow_provider_reference),
    };
    if contains_reference {
        return Err(GeneratorError::usage(format!(
            "workflow contains retired provider reference ({}): {}",
            RETIRED_WORKFLOW_PROVIDER_REPOSITORIES.join(", "),
            path.display(),
        )));
    }
    Ok(())
}

fn is_retired_workflow_provider_repository(root: &Path) -> bool {
    let Some(repository) = local_github_repository(root) else {
        return false;
    };
    RETIRED_WORKFLOW_PROVIDER_REPOSITORIES
        .iter()
        .any(|candidate| *candidate == repository)
}

fn yaml_contains_retired_workflow_provider(value: &serde_yaml::Value) -> bool {
    match value {
        serde_yaml::Value::Mapping(mapping) => mapping.iter().any(|(key, value)| {
            (key == "uses"
                && value
                    .as_str()
                    .is_some_and(is_retired_workflow_provider_reference))
                || yaml_contains_retired_workflow_provider(value)
        }),
        serde_yaml::Value::Sequence(sequence) => {
            sequence.iter().any(yaml_contains_retired_workflow_provider)
        }
        serde_yaml::Value::Tagged(tagged) => {
            yaml_contains_retired_workflow_provider(tagged.value())
        }
        serde_yaml::Value::Null
        | serde_yaml::Value::Bool(_)
        | serde_yaml::Value::Number(_)
        | serde_yaml::Value::String(_) => false,
    }
}

fn workflow_uses_value(line: &str) -> Option<&str> {
    let line = line.trim_start();
    let line = line.strip_prefix('-').map_or(line, str::trim_start);
    let (key, value) = line.split_once(':')?;
    (key.trim() == "uses").then_some(value)
}

fn is_retired_workflow_provider_reference(value: &str) -> bool {
    let value = value
        .split_once('#')
        .map_or(value, |(value, _)| value)
        .trim()
        .trim_matches(|character| matches!(character, '\'' | '"'));
    let path = value.split_once('@').map_or(value, |(path, _)| path);
    RETIRED_WORKFLOW_PROVIDER_REPOSITORIES
        .iter()
        .any(|repository| {
            let repository_length = repository.len();
            let Some(prefix) = path.get(..repository_length) else {
                return false;
            };
            prefix.eq_ignore_ascii_case(repository)
                && path
                    .as_bytes()
                    .get(repository_length)
                    .is_none_or(|byte| *byte == b'/')
        })
}

fn load_workflow_templates(
    root: &Path,
    mut config: ProjectConfig,
) -> Result<ProjectConfig, GeneratorError> {
    let directory = root.join(WORKFLOW_TEMPLATE_DIR);
    if !directory.is_dir() {
        return Ok(config);
    }
    let entries = fs::read_dir(&directory)
        .map_err(|error| GeneratorError::io("read workflow templates", &directory, &error))?;
    let reject_retired_provider_references = !is_retired_workflow_provider_repository(root);
    let mut names = Vec::new();
    for entry in entries {
        let entry = entry.map_err(|error| {
            GeneratorError::io("read workflow template entry", &directory, &error)
        })?;
        let path = entry.path();
        let file_type = entry
            .file_type()
            .map_err(|error| GeneratorError::io("read workflow template type", &path, &error))?;
        let Some(name) = path.file_name().and_then(|value| value.to_str()) else {
            continue;
        };
        let extension = path.extension().and_then(|value| value.to_str());
        if !file_type.is_file() || !matches!(extension, Some("yml" | "yaml")) {
            continue;
        }
        let content = fs::read_to_string(&path)
            .map_err(|error| GeneratorError::io("read workflow template", &path, &error))?;
        let body = content.strip_prefix(GENERATED_HEADER).ok_or_else(|| {
            GeneratorError::usage(format!(
                "workflow template is not generated by velnor-workflow: {}",
                path.display()
            ))
        })?;
        if reject_retired_provider_references {
            reject_retired_workflow_provider_reference(&path, body)?;
        }
        names.push(name.to_owned());
        config
            .workflow_templates
            .insert(name.to_owned(), body.to_owned());
    }
    names.sort();
    names.dedup();
    if !names.is_empty() {
        if config.repository.is_empty() {
            config.workflow_files = names;
            config.adopted_workflow_surface = true;
        } else {
            for name in names {
                if !config.workflow_files.contains(&name) {
                    config.workflow_files.push(name);
                }
            }
        }
    }
    Ok(config)
}

fn strip_workflow_generator_header(content: &str) -> &str {
    if let Some(body) = content.strip_prefix(GENERATED_HEADER) {
        return body;
    }
    let Some((first, body)) = content.split_once('\n') else {
        return content;
    };
    if first.starts_with("# Generated by ") {
        body
    } else {
        content
    }
}

fn adopt_existing_workflow_templates(
    root: &Path,
    mut config: ProjectConfig,
) -> Result<ProjectConfig, GeneratorError> {
    let workflows = root.join(".github/workflows");
    if !workflows.is_dir() {
        return Ok(config);
    }
    let entries = fs::read_dir(&workflows)
        .map_err(|error| GeneratorError::io("read workflows", &workflows, &error))?;
    let mut existing = Vec::new();
    for entry in entries {
        let entry =
            entry.map_err(|error| GeneratorError::io("read workflow entry", &workflows, &error))?;
        let path = entry.path();
        let file_type = entry
            .file_type()
            .map_err(|error| GeneratorError::io("read workflow type", &path, &error))?;
        let Some(name) = path.file_name().and_then(|value| value.to_str()) else {
            continue;
        };
        let extension = path.extension().and_then(|value| value.to_str());
        if !file_type.is_file() || !matches!(extension, Some("yml" | "yaml")) {
            continue;
        }
        existing.push(name.to_owned());
    }
    existing.sort();
    existing.dedup();
    if existing.is_empty() {
        return Ok(config);
    }

    let local_velnor = config.repository == "tailrocks/velnor";
    let already_adopted = config.adopted_workflow_surface;
    let reject_retired_provider_references = !is_retired_workflow_provider_repository(root);
    if !local_velnor && !already_adopted {
        config.workflow_files.clone_from(&existing);
    }
    let generated = generated_files(&config);
    for name in existing {
        let output = PathBuf::from(".github/workflows").join(&name);
        if local_velnor && generated.contains_key(&output) {
            continue;
        }
        let path = root.join(&output);
        let content = fs::read_to_string(&path)
            .map_err(|error| GeneratorError::io("read workflow for adoption", &path, &error))?;
        if reject_retired_provider_references {
            reject_retired_workflow_provider_reference(&path, &content)?;
        }
        if already_adopted
            && content.starts_with(GENERATED_HEADER)
            && !config.workflow_templates.contains_key(&name)
        {
            continue;
        }
        if config.workflow_templates.contains_key(&name) {
            continue;
        }
        config
            .workflow_templates
            .insert(name, strip_workflow_generator_header(&content).to_owned());
    }
    if !local_velnor {
        config.adopted_workflow_surface = true;
    }
    config.workflow_files = config
        .workflow_files
        .into_iter()
        .chain(config.workflow_templates.keys().cloned())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    normalize_adopted_workflow_contracts(root, &mut config)?;
    Ok(config)
}

fn normalize_adopted_workflow_contracts(
    root: &Path,
    config: &mut ProjectConfig,
) -> Result<(), GeneratorError> {
    for class in ["code", "native", "tap", "apt", "fixture"] {
        let template = root.join("templates").join(class).join("ci.yml");
        if !template.is_file() {
            continue;
        }
        let bytes = fs::read(&template)
            .map_err(|error| GeneratorError::io("read consumer template", &template, &error))?;
        let digest = Sha256::digest(bytes);
        let digest = digest
            .iter()
            .fold(String::with_capacity(64), |mut output, byte| {
                let _ = write!(output, "{byte:02x}");
                output
            });
        let workflow = format!("ci-{class}.yml");
        let Some(body) = config.workflow_templates.get_mut(&workflow) else {
            continue;
        };
        replace_embedded_template_digest(body, &digest);
    }
    Ok(())
}

fn replace_embedded_template_digest(body: &mut String, digest: &str) {
    let marker = "EXPECTED_CALLER_TEMPLATE_SHA256:";
    if !body.contains(marker) {
        return;
    }
    let mut rendered = String::with_capacity(body.len());
    for segment in body.split_inclusive('\n') {
        let newline = segment.ends_with('\n').then_some('\n');
        let line = segment.strip_suffix('\n').unwrap_or(segment);
        if let Some(index) = line.find(marker) {
            let value_start = index + marker.len();
            let whitespace = line[value_start..]
                .chars()
                .take_while(char::is_ascii_whitespace)
                .collect::<String>();
            let prefix_end = value_start + whitespace.len();
            rendered.push_str(&line[..prefix_end]);
            rendered.push_str(digest);
            if let Some(newline) = newline {
                rendered.push(newline);
            }
        } else {
            rendered.push_str(segment);
        }
    }
    *body = rendered;
}

fn catalog_unit(
    id: &str,
    label: &str,
    kind: UnitKind,
    watch: &[&str],
    pr_commands: &[&str],
    full_commands: &[&str],
    cache: Option<CacheSpec>,
) -> Unit {
    Unit {
        id: id.to_owned(),
        label: label.to_owned(),
        kind,
        root: ".".to_owned(),
        watch: watch.iter().map(|value| (*value).to_owned()).collect(),
        pr_commands: pr_commands
            .iter()
            .map(|value| (*value).to_owned())
            .collect(),
        full_commands: full_commands
            .iter()
            .map(|value| (*value).to_owned())
            .collect(),
        github_pr_commands: None,
        github_full_commands: None,
        velnor_pr_commands: None,
        velnor_full_commands: None,
        depends_on: Vec::new(),
        cache,
        tool_version: None,
    }
}

fn unit_with_dependencies(mut unit: Unit, dependencies: &[&str]) -> Unit {
    unit.depends_on = dependencies
        .iter()
        .map(|dependency| (*dependency).to_owned())
        .collect();
    unit
}

fn cargo_cache() -> CacheSpec {
    CacheSpec {
        key_files: vec![
            ".cargo/**".to_owned(),
            "Cargo.toml".to_owned(),
            "Cargo.lock".to_owned(),
            "rust-toolchain.toml".to_owned(),
            "rust-toolchain".to_owned(),
        ],
        paths: vec![
            "~/.cargo/registry".to_owned(),
            "~/.cargo/git".to_owned(),
            "~/.cache/sccache".to_owned(),
        ],
    }
}

fn catalog_rust_unit(label: &str, full_command: &str) -> Unit {
    let full_commands = [full_command, PER_CRATE_TEST_COMMAND];
    catalog_unit(
        "rust",
        label,
        UnitKind::Rust,
        &[
            "Cargo.toml",
            "Cargo.lock",
            "**/*.rs",
            "**/Cargo.toml",
            ".cargo/**",
            "rust-toolchain*",
        ],
        &[
            "cargo fmt --all -- --check",
            "cargo clippy --workspace --locked --all-targets --all-features -- -D warnings",
            PER_CRATE_TEST_COMMAND,
        ],
        &full_commands,
        Some(cargo_cache()),
    )
}

