    #[test]
    fn adoption_snapshots_existing_workflows_and_reloads_them_from_templates() {
        let root = temporary_repository("adopt-existing-workflows");
        let workflow = root.join(".github/workflows/ci.yml");
        must(
            fs::create_dir_all(must_some(workflow.parent(), "workflow parent")),
            "create workflow directory",
        );
        let existing = "# Generated by another-workflow-tool. DO NOT EDIT.\nname: CI\n";
        must(fs::write(&workflow, existing), "write existing workflow");

        let config = must(
            scan_repository(&root, RunnerMode::Github),
            "scan workflow-only repository",
        );
        assert!(config.units.is_empty());
        let config = must(
            adopt_existing_workflow_templates(&root, config),
            "adopt existing workflow",
        );
        assert_eq!(config.workflow_files, vec!["ci.yml"]);
        assert_eq!(
            config.workflow_templates.get("ci.yml"),
            Some(&"name: CI\n".to_owned())
        );
        let files = generated_files(&config);
        must(
            write_generated_with_options(&root, &files, false, false, true, true),
            "write adopted workflow",
        );
        let rendered = must(fs::read_to_string(&workflow), "read adopted workflow");
        assert!(rendered.starts_with(GENERATED_HEADER));
        assert!(!rendered.contains("another-workflow-tool"));
        assert!(root.join(WORKFLOW_TEMPLATE_DIR).join("ci.yml").is_file());

        let reloaded = must(
            scan_repository(&root, RunnerMode::Github),
            "reload adopted workflow",
        );
        assert_eq!(reloaded, config);
        let reloaded_files = generated_files(&reloaded);
        assert!(matches!(
            write_generated(&root, &reloaded_files, false, true, false),
            Ok(WriteOutcome::Unchanged)
        ));
        let _ = fs::remove_dir_all(root);
    }

