    #[test]
    fn generate_removes_absent_stale_entry_from_ownership_state() {
        let root = temporary_repository("refresh-absent-stale-ownership-entry");
        let current = BTreeMap::from([(
            PathBuf::from(".github/workflows/ci-pr.yml"),
            format!("{GENERATED_HEADER}name: current\n"),
        )]);
        let stale = PathBuf::from(".github/workflows/preview.yml");
        let mut previous = current.clone();
        previous.insert(stale.clone(), format!("{GENERATED_HEADER}name: stale\n"));
        must(
            write_generated(&root, &previous, false, false, false),
            "write previous generated layout",
        );
        must(
            fs::remove_file(root.join(&stale)),
            "remove stale file outside generator",
        );

        let outcome = must(
            write_generated(&root, &current, false, false, false),
            "refresh stale ownership metadata",
        );
        assert!(matches!(
            outcome,
            WriteOutcome::Written { ref changed, ref created }
                if changed == &[PathBuf::from(OWNERSHIP_STATE)] && created.is_empty()
        ));
        assert_eq!(
            must(
                fs::read_to_string(root.join(OWNERSHIP_STATE)),
                "read refreshed ownership state",
            ),
            ownership_state_content(&current)
        );
        let _ = fs::remove_dir_all(root);
    }

