    #[test]
    fn unowned_legacy_guide_is_preserved() {
        let root = temporary_repository("unowned-generated-guide");
        must(
            fs::write(
                root.join("Cargo.toml"),
                "[package]\nname = \"fixture\"\nversion = \"0.1.0\"\n",
            ),
            "write manifest",
        );
        let guide = root.join(".github/UNIFIED-ACTIONS.md");
        must(
            fs::create_dir_all(must_some(guide.parent(), "guide parent")),
            "create guide parent",
        );
        must(fs::write(&guide, "# local guide\n"), "write unowned guide");
        let config = must(
            scan_repository(&root, RunnerMode::Github),
            "scan unowned-guide repository",
        );
        let files = generated_files(&config);
        must(
            write_generated(&root, &files, false, false, false),
            "generate beside unowned guide",
        );
        assert_eq!(
            must(fs::read_to_string(&guide), "read preserved guide"),
            "# local guide\n"
        );
        let _ = fs::remove_dir_all(root);
    }

    #[cfg(unix)]
    #[test]
    fn symlinked_legacy_guide_is_not_removed() {
        let root = temporary_repository("symlinked-generated-guide");
        let outside = temporary_repository("symlinked-generated-guide-target");
        must(
            fs::write(
                root.join("Cargo.toml"),
                "[package]\nname = \"fixture\"\nversion = \"0.1.0\"\n",
            ),
            "write manifest",
        );
        let config = must(
            scan_repository(&root, RunnerMode::Github),
            "scan symlinked-guide repository",
        );
        let current = generated_files(&config);
        let guide = PathBuf::from(".github/UNIFIED-ACTIONS.md");
        let mut previous = current.clone();
        previous.insert(guide.clone(), format!("{GENERATED_HEADER}legacy guide\n"));
        must(
            write_generated(&root, &previous, false, false, false),
            "write previous generated layout",
        );
        must(fs::remove_file(root.join(&guide)), "remove regular guide");
        must(
            std::os::unix::fs::symlink(&outside, root.join(&guide)),
            "create guide symlink",
        );
        must(
            write_ownership_state(&root, &previous),
            "restore legacy guide ownership state",
        );
        let error = must_some(
            write_generated(&root, &current, false, false, false).err(),
            "reject symlinked legacy guide",
        );
        assert!(error.to_string().contains("symlinked stale generated file"));
        assert!(fs::symlink_metadata(root.join(&guide)).is_ok());
        assert!(must(fs::read_dir(&outside), "read outside directory")
            .next()
            .is_none());
        let _ = fs::remove_dir_all(root);
        let _ = fs::remove_dir_all(outside);
    }

