    #[test]
    fn explicit_output_path_writes_generated_tree_outside_local_target() {
        let source = temporary_repository("explicit-output-source");
        let output_parent = temporary_repository("explicit-output-destination");
        let output = output_parent.join("nested-output");
        must(
            fs::write(
                source.join("Cargo.toml"),
                "[package]\nname = \"fixture\"\nversion = \"0.1.0\"\n",
            ),
            "write source manifest",
        );
        let cli = Cli {
            target: source.to_string_lossy().into_owned(),
            default_branch: Some("main".to_owned()),
            output: Some(output.clone()),
            runners: RunnerMode::Github,
            dry_run: false,
            check: false,
            force: false,
            adopt: false,
            plain: true,
        };

        must(run(&cli), "generate into explicit output path");

        assert!(output.join(".github/ci/project.toml").is_file());
        assert!(output.join(".github/workflows/ci-pr.yml").is_file());
        assert!(!source.join(".github").exists());
        let _ = fs::remove_dir_all(source);
        let _ = fs::remove_dir_all(output_parent);
    }

    #[test]
    fn force_refuses_to_replace_manually_modified_generated_file() {
        let root = temporary_repository("manual-generated-edit");
        must(
            fs::write(
                root.join("Cargo.toml"),
                "[package]\nname = \"fixture\"\nversion = \"0.1.0\"\n",
            ),
            "write manifest",
        );
        let config = must(
            scan_repository(&root, RunnerMode::Github),
            "scan test repository",
        );
        let files = generated_files(&config);
        must(
            write_generated(&root, &files, false, false, false),
            "generate files and ownership state",
        );
        let workflow = root.join(".github/workflows/ci-pr.yml");
        let custom = format!(
            "{}# local extension\n",
            must(fs::read_to_string(&workflow), "read workflow")
        );
        must(fs::write(&workflow, &custom), "extend generated workflow");

        let error = must_some(
            write_generated(&root, &files, false, false, true).err(),
            "force must preserve manual edit",
        );
        assert!(error
            .to_string()
            .contains("manually modified generated file"));
        assert_eq!(
            must(fs::read_to_string(&workflow), "read preserved workflow"),
            custom
        );
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn explicit_adoption_refreshes_modified_workflow_template() {
        let root = temporary_repository("adopt-modified-workflow-template");
        let relative = PathBuf::from(WORKFLOW_TEMPLATE_DIR).join("ci.yml");
        let path = root.join(&relative);
        must(
            fs::create_dir_all(must_some(path.parent(), "template parent")),
            "create template parent",
        );
        must(fs::write(&path, "old template\n"), "write template");

        let preimage = must(
            capture_file_preimage(&path, &relative),
            "capture template preimage",
        );
        let mut files = BTreeMap::new();
        files.insert(relative.clone(), "new template\n".to_owned());
        let mut ownership = BTreeMap::new();
        ownership.insert(relative.clone(), content_digest("different template\n"));
        let mut preimages = BTreeMap::new();
        preimages.insert(relative, preimage);

        let refresh = must(
            verify_generated_ownership(&files, Some(&ownership), &preimages, true),
            "adopt modified template",
        );
        assert!(refresh);
        let _ = fs::remove_dir_all(root);
    }

